-- Phase 5.8 restaurant CRM, customer marketing preferences and saved segments.
create table if not exists public.restaurant_marketing_settings (
  restaurant_id uuid primary key references public.restaurants(id) on delete cascade,
  timezone text not null default 'Europe/London', quiet_hours_start time not null default '21:00', quiet_hours_end time not null default '08:00',
  high_spender_pence integer not null default 10000 check(high_spender_pence>=0), low_spender_pence integer not null default 3000 check(low_spender_pence>=0),
  referral_champion_threshold integer not null default 3 check(referral_champion_threshold>0), max_email_sends_per_day integer not null default 5000 check(max_email_sends_per_day>0),
  max_notification_sends_per_day integer not null default 10000 check(max_notification_sends_per_day>0), max_sends_per_customer_per_day integer not null default 3 check(max_sends_per_customer_per_day>0),
  rate_limit_per_minute integer not null default 250 check(rate_limit_per_minute>0), attribution_window_days integer not null default 7 check(attribution_window_days between 1 and 90),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.customer_marketing_preferences (
  customer_user_id uuid primary key references auth.users(id) on delete cascade, marketing_emails boolean not null default false,
  promotional_notifications boolean not null default false, loyalty_notifications boolean not null default true, referral_notifications boolean not null default true,
  birthday_notifications boolean not null default true, global_opt_out boolean not null default false, consent_updated_at timestamptz not null default now(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.customer_restaurant_marketing_preferences (
  restaurant_id uuid not null references public.restaurants(id) on delete cascade, customer_user_id uuid not null references auth.users(id) on delete cascade,
  marketing_emails boolean not null default true, promotional_notifications boolean not null default true, loyalty_notifications boolean not null default true,
  referral_notifications boolean not null default true, birthday_notifications boolean not null default true, restaurant_opt_out boolean not null default false,
  consent_updated_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(restaurant_id,customer_user_id)
);
create table if not exists public.restaurant_customer_notes (
  id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  customer_user_id uuid not null references auth.users(id) on delete cascade, note text not null check(char_length(note) between 1 and 4000),
  created_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.restaurant_customer_segments (
  id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade,
  name text not null check(char_length(name) between 1 and 120), description text, filter_config jsonb not null default '{}'::jsonb,
  is_active boolean not null default true, created_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(restaurant_id,name)
);
create index if not exists restaurant_customer_notes_customer_idx on public.restaurant_customer_notes(restaurant_id,customer_user_id,created_at desc);
create index if not exists restaurant_customer_segments_active_idx on public.restaurant_customer_segments(restaurant_id,is_active,created_at desc);
create index if not exists orders_restaurant_customer_paid_idx on public.orders(restaurant_id,customer_user_id,created_at desc) where customer_user_id is not null and payment_status='paid' and order_status<>'rejected';
create index if not exists order_items_order_menu_item_idx on public.order_items(order_id,menu_item_id);
create index if not exists customer_reward_issuances_crm_idx on public.customer_reward_issuances(restaurant_id,customer_user_id,status,created_at desc);
create index if not exists customer_stamp_cards_crm_idx on public.customer_stamp_cards(restaurant_id,customer_user_id,is_active);
create index if not exists customer_referrals_referrer_crm_idx on public.customer_referrals(restaurant_id,referrer_user_id,status,created_at desc);
create index if not exists customer_challenge_progress_crm_idx on public.customer_challenge_progress(restaurant_id,customer_user_id,status,updated_at desc);
create index if not exists customer_vip_memberships_crm_idx on public.customer_vip_memberships(restaurant_id,customer_user_id,current_tier_id);
alter table public.restaurant_marketing_settings enable row level security; alter table public.customer_marketing_preferences enable row level security;
alter table public.customer_restaurant_marketing_preferences enable row level security; alter table public.restaurant_customer_notes enable row level security; alter table public.restaurant_customer_segments enable row level security;
create policy restaurant_marketing_settings_member_select on public.restaurant_marketing_settings for select using(public.is_restaurant_member(restaurant_id));
create policy restaurant_marketing_settings_member_write on public.restaurant_marketing_settings for all using(public.is_restaurant_member(restaurant_id)) with check(public.is_restaurant_member(restaurant_id));
create policy customer_marketing_preferences_self on public.customer_marketing_preferences for all using((select auth.uid())=customer_user_id) with check((select auth.uid())=customer_user_id);
create policy customer_restaurant_marketing_preferences_select on public.customer_restaurant_marketing_preferences for select using((select auth.uid())=customer_user_id or public.is_restaurant_member(restaurant_id));
create policy customer_restaurant_marketing_preferences_self_write on public.customer_restaurant_marketing_preferences for all using((select auth.uid())=customer_user_id) with check((select auth.uid())=customer_user_id);
create policy restaurant_customer_notes_member_select on public.restaurant_customer_notes for select using(public.is_restaurant_member(restaurant_id));
create policy restaurant_customer_notes_member_write on public.restaurant_customer_notes for all using(public.is_restaurant_member(restaurant_id)) with check(public.is_restaurant_member(restaurant_id));
create policy restaurant_customer_segments_member_select on public.restaurant_customer_segments for select using(public.is_restaurant_member(restaurant_id));
create policy restaurant_customer_segments_member_write on public.restaurant_customer_segments for all using(public.is_restaurant_member(restaurant_id)) with check(public.is_restaurant_member(restaurant_id));

create or replace function public.marketing_segment_filter_matches(p_metrics jsonb,p_filter jsonb) returns boolean language sql immutable set search_path='' as $$
 select (not(p_filter?'min_lifetime_spend_pence') or coalesce((p_metrics->>'lifetime_spend_pence')::bigint,0)>=(p_filter->>'min_lifetime_spend_pence')::bigint)
 and(not(p_filter?'max_lifetime_spend_pence') or coalesce((p_metrics->>'lifetime_spend_pence')::bigint,0)<=(p_filter->>'max_lifetime_spend_pence')::bigint)
 and(not(p_filter?'min_orders') or coalesce((p_metrics->>'total_orders')::integer,0)>=(p_filter->>'min_orders')::integer)
 and(not(p_filter?'max_orders') or coalesce((p_metrics->>'total_orders')::integer,0)<=(p_filter->>'max_orders')::integer)
 and(not(p_filter?'inactive_days_min') or coalesce((p_metrics->>'days_since_last_order')::integer,999999)>=(p_filter->>'inactive_days_min')::integer)
 and(not(p_filter?'inactive_days_max') or coalesce((p_metrics->>'days_since_last_order')::integer,999999)<=(p_filter->>'inactive_days_max')::integer)
 and(not(p_filter?'vip_tier_id') or p_metrics->>'vip_tier_id'=p_filter->>'vip_tier_id')
 and(not(p_filter?'birthday_month') or coalesce((p_metrics->>'birthday_month')::integer,0)=(p_filter->>'birthday_month')::integer)
 and(not(p_filter?'has_reward_available') or coalesce((p_metrics->>'has_reward_available')::boolean,false)=(p_filter->>'has_reward_available')::boolean)
 and(not(p_filter?'has_one_stamp_remaining') or coalesce((p_metrics->>'has_one_stamp_remaining')::boolean,false)=(p_filter->>'has_one_stamp_remaining')::boolean)
 and(not(p_filter?'has_challenge_progress') or coalesce((p_metrics->>'has_challenge_progress')::boolean,false)=(p_filter->>'has_challenge_progress')::boolean)
 and(not(p_filter?'min_referrals') or coalesce((p_metrics->>'qualified_referrals')::integer,0)>=(p_filter->>'min_referrals')::integer)
$$;
create or replace function public.get_customer_marketing_preferences() returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_user uuid:=auth.uid();v_result jsonb;begin if v_user is null then raise exception 'Authentication required' using errcode='42501';end if;select jsonb_build_object('global',coalesce((select to_jsonb(g)-'customer_user_id'-'created_at'-'updated_at' from public.customer_marketing_preferences g where g.customer_user_id=v_user),jsonb_build_object('marketing_emails',false,'promotional_notifications',false,'loyalty_notifications',true,'referral_notifications',true,'birthday_notifications',true,'global_opt_out',false)),'restaurants',coalesce((select jsonb_agg(jsonb_build_object('restaurant_id',rp.restaurant_id,'restaurant_name',r.name,'marketing_emails',rp.marketing_emails,'promotional_notifications',rp.promotional_notifications,'loyalty_notifications',rp.loyalty_notifications,'referral_notifications',rp.referral_notifications,'birthday_notifications',rp.birthday_notifications,'restaurant_opt_out',rp.restaurant_opt_out,'consent_updated_at',rp.consent_updated_at) order by r.name) from public.customer_restaurant_marketing_preferences rp join public.restaurants r on r.id=rp.restaurant_id where rp.customer_user_id=v_user),'[]'::jsonb)) into v_result;return v_result;end $$;
create or replace function public.update_customer_marketing_preferences(p_restaurant_id uuid default null,p_marketing_emails boolean default null,p_promotional_notifications boolean default null,p_loyalty_notifications boolean default null,p_referral_notifications boolean default null,p_birthday_notifications boolean default null,p_opt_out boolean default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid();begin if v_user is null then raise exception 'Authentication required' using errcode='42501';end if;if p_restaurant_id is null then insert into public.customer_marketing_preferences(customer_user_id,marketing_emails,promotional_notifications,loyalty_notifications,referral_notifications,birthday_notifications,global_opt_out,consent_updated_at,updated_at) values(v_user,coalesce(p_marketing_emails,false),coalesce(p_promotional_notifications,false),coalesce(p_loyalty_notifications,true),coalesce(p_referral_notifications,true),coalesce(p_birthday_notifications,true),coalesce(p_opt_out,false),now(),now()) on conflict(customer_user_id) do update set marketing_emails=coalesce(p_marketing_emails,customer_marketing_preferences.marketing_emails),promotional_notifications=coalesce(p_promotional_notifications,customer_marketing_preferences.promotional_notifications),loyalty_notifications=coalesce(p_loyalty_notifications,customer_marketing_preferences.loyalty_notifications),referral_notifications=coalesce(p_referral_notifications,customer_marketing_preferences.referral_notifications),birthday_notifications=coalesce(p_birthday_notifications,customer_marketing_preferences.birthday_notifications),global_opt_out=coalesce(p_opt_out,customer_marketing_preferences.global_opt_out),consent_updated_at=now(),updated_at=now();else insert into public.customer_restaurant_marketing_preferences(restaurant_id,customer_user_id,marketing_emails,promotional_notifications,loyalty_notifications,referral_notifications,birthday_notifications,restaurant_opt_out,consent_updated_at,updated_at) values(p_restaurant_id,v_user,coalesce(p_marketing_emails,true),coalesce(p_promotional_notifications,true),coalesce(p_loyalty_notifications,true),coalesce(p_referral_notifications,true),coalesce(p_birthday_notifications,true),coalesce(p_opt_out,false),now(),now()) on conflict(restaurant_id,customer_user_id) do update set marketing_emails=coalesce(p_marketing_emails,customer_restaurant_marketing_preferences.marketing_emails),promotional_notifications=coalesce(p_promotional_notifications,customer_restaurant_marketing_preferences.promotional_notifications),loyalty_notifications=coalesce(p_loyalty_notifications,customer_restaurant_marketing_preferences.loyalty_notifications),referral_notifications=coalesce(p_referral_notifications,customer_restaurant_marketing_preferences.referral_notifications),birthday_notifications=coalesce(p_birthday_notifications,customer_restaurant_marketing_preferences.birthday_notifications),restaurant_opt_out=coalesce(p_opt_out,customer_restaurant_marketing_preferences.restaurant_opt_out),consent_updated_at=now(),updated_at=now();end if;return public.get_customer_marketing_preferences();end $$;
create or replace function public.upsert_restaurant_crm_segment(p_restaurant_id uuid,p_segment_id uuid,p_name text,p_description text,p_filter_config jsonb,p_is_active boolean default true) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid;begin if not public.is_restaurant_member(p_restaurant_id) then raise exception 'Restaurant access denied' using errcode='42501';end if;if p_segment_id is null then insert into public.restaurant_customer_segments(restaurant_id,name,description,filter_config,is_active,created_by) values(p_restaurant_id,btrim(p_name),nullif(btrim(p_description),''),coalesce(p_filter_config,'{}'),coalesce(p_is_active,true),auth.uid()) returning id into v_id;else update public.restaurant_customer_segments set name=btrim(p_name),description=nullif(btrim(p_description),''),filter_config=coalesce(p_filter_config,'{}'),is_active=coalesce(p_is_active,true),updated_at=now() where id=p_segment_id and restaurant_id=p_restaurant_id returning id into v_id;if v_id is null then raise exception 'Segment not found';end if;end if;return v_id;end $$;
create or replace function public.add_restaurant_customer_note(p_restaurant_id uuid,p_customer_user_id uuid,p_note text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid;begin if not public.is_restaurant_member(p_restaurant_id) then raise exception 'Restaurant access denied' using errcode='42501';end if;if not exists(select 1 from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id) then raise exception 'Customer not found';end if;insert into public.restaurant_customer_notes(restaurant_id,customer_user_id,note,created_by) values(p_restaurant_id,p_customer_user_id,btrim(p_note),auth.uid()) returning id into v_id;return v_id;end $$;
create or replace function public.delete_restaurant_customer_note(p_note_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare v_restaurant uuid;begin select restaurant_id into v_restaurant from public.restaurant_customer_notes where id=p_note_id;if v_restaurant is null or not public.is_restaurant_member(v_restaurant) then raise exception 'Restaurant access denied' using errcode='42501';end if;delete from public.restaurant_customer_notes where id=p_note_id;return found;end $$;
revoke all on function public.marketing_segment_filter_matches(jsonb,jsonb),public.get_customer_marketing_preferences(),public.update_customer_marketing_preferences(uuid,boolean,boolean,boolean,boolean,boolean,boolean),public.upsert_restaurant_crm_segment(uuid,uuid,text,text,jsonb,boolean),public.add_restaurant_customer_note(uuid,uuid,text),public.delete_restaurant_customer_note(uuid) from public;
grant execute on function public.get_customer_marketing_preferences(),public.update_customer_marketing_preferences(uuid,boolean,boolean,boolean,boolean,boolean,boolean),public.upsert_restaurant_crm_segment(uuid,uuid,text,text,jsonb,boolean),public.add_restaurant_customer_note(uuid,uuid,text),public.delete_restaurant_customer_note(uuid) to authenticated;
